using OcctSharp.Generator.Emission;
using OcctSharp.Generator.Model;
using OcctSharp.Generator.Transformation;
using OcctSharp.Generator.TypeMapping;
namespace OcctSharp.Generator.Tests;
public sealed class NumericMatricesContractTests {
 static BindingDeclaration Declaration(CopiedCollectionOperationContract.Operation op)=>new(op.StableId,op.NativeName,BindingDeclarationKind.Method,op.NativeName.Split("::")[0]+".hxx",1,1){NativeSignature=op.Signature,Access=BindingAccess.Public,ProductModule=OcctProductModule.Foundation};
 [Fact]public void OnlyExactAuditedAccessibleSignaturesAreAdmitted(){var d=Declaration(NumericMatricesOperationContract.Operations.Values.First(o=>!o.Supporting));Assert.True(NumericMatricesOperationContract.Contains(d));Assert.False(NumericMatricesOperationContract.Contains(d with{NativeSignature=d.NativeSignature+" "}));Assert.False(NumericMatricesOperationContract.Contains(d with{IsDeleted=true}));Assert.False(NumericMatricesOperationContract.Contains(d with{Access=BindingAccess.Private}));Assert.False(NumericMatricesOperationContract.Contains(d with{SupportState=BindingSupportState.Manual}));}
 [Fact]public void PartialContractCannotPublishAnInflatedManifest(){var d=Declaration(NumericMatricesOperationContract.Operations.Values.First());Assert.Throws<InvalidDataException>(()=>NumericMatricesOperationEmitter.Emit("8.0.1",new BindingModel([d])));}
 [Fact]public void DeterministicOutputExcludesReusedManualIds(){var manual=NumericMatricesOperationContract.Operations.Values.First(o=>o.Supporting);var rows=NumericMatricesOperationContract.Operations.Values.Select(o=>Declaration(o) with{SupportState=o==manual?BindingSupportState.Manual:BindingSupportState.Pending}).ToArray();var a=NumericMatricesOperationEmitter.Emit("8.0.1",new BindingModel(rows));var b=NumericMatricesOperationEmitter.Emit("8.0.1",new BindingModel(rows.Reverse()));Assert.Equal(3,a.Files.Count);Assert.Equal(a.Files.Select(f=>f.Content),b.Files.Select(f=>f.Content));Assert.DoesNotContain(manual.StableId,a.SourceStableIds);Assert.All(a.Files,f=>Assert.Equal(OcctProductModule.Foundation,f.ProductModule));}
 [Fact]public void PrivateSolverProjectionDoesNotChangeGlobalMapping(){var t=new BindingType("math_SVD","math_SVD","math_SVD","math_SVD",[new(BindingTypeLayerKind.Value,false)],null,[],false,null);var map=InitialTypeMap.FromModel(new BindingModel([]));var d=Declaration(NumericMatricesOperationContract.Operations.Values.First(o=>o.NativeName=="math_SVD::PseudoInverse"));Assert.False(map.TryMap(t,BindingTypeUsage.ReturnValue,out _));Assert.True(NumericMatricesOperationContract.TryMap(d,t,BindingTypeUsage.ReturnValue,map,out var p));Assert.Equal("TM018",p!.RuleId);Assert.False(NumericMatricesOperationContract.TryMap(d with{StableId="unapproved"},t,BindingTypeUsage.ReturnValue,map,out _));}
 [Fact]public void BorrowedStorageAndSolverCopiesStayExcluded(){Assert.DoesNotContain(NumericMatricesOperationContract.Operations.Values,o=>o.NativeName.EndsWith("::Dump",StringComparison.Ordinal)||o.NativeName=="math_Matrix::Initialized"||o.Signature.Contains("void *",StringComparison.Ordinal)||o.Signature.Contains("&&",StringComparison.Ordinal));Assert.DoesNotContain(NumericMatricesOperationContract.Operations.Values,o=>o.NativeName=="math_SVD::math_SVD"&&o.Signature.Contains("const math_SVD &",StringComparison.Ordinal));}
}
